#!/usr/bin/env node
/* Manifest referential-integrity guard.
 *
 * Every path the manifest names must exist in the built output. Ported from
 * the validate.py in the advanced-bookmarks extension, and worth more here
 * than it was there: that manifest was hand-written, this one is generated by
 * WXT from wxt.config.ts, so a wrong path is a config mistake that produces a
 * clean build and an extension that fails to load with a message only visible
 * on chrome://extensions.
 */

import { existsSync, readFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { report } from './lib/scan.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const candidates = ['chrome-mv3', 'chrome'].map((d) => join(root, 'dist', d));
const distDir = candidates.find((d) => existsSync(join(d, 'manifest.json')));

if (!distDir) {
  console.error('\n✗ manifest refs guard: no built manifest found. Run `npm run build` first.\n');
  process.exit(1);
}

const manifest = JSON.parse(readFileSync(join(distDir, 'manifest.json'), 'utf8'));

const failures = [];
const notes = [];
const seen = new Set();

function check(path, where) {
  if (!path || typeof path !== 'string') return;
  if (/^https?:\/\//i.test(path)) {
    failures.push(`${where}: points at a remote URL (${path}) -- Headsmith ships no remote subresources`);
    return;
  }
  const relPath = path.replace(/^\//, '');
  if (seen.has(relPath)) return;
  seen.add(relPath);
  if (existsSync(join(distDir, relPath))) notes.push(`ok: ${relPath}`);
  else failures.push(`${where}: missing file ${relPath}`);
}

check(manifest.background?.service_worker, 'background.service_worker');
check(manifest.action?.default_popup, 'action.default_popup');
check(manifest.options_page, 'options_page');
check(manifest.options_ui?.page, 'options_ui.page');
check(manifest.devtools_page, 'devtools_page');
check(manifest.chrome_url_overrides?.newtab, 'chrome_url_overrides.newtab');
check(manifest.sandbox?.pages, 'sandbox.pages');

for (const [size, path] of Object.entries(manifest.icons ?? {})) check(path, `icons.${size}`);
for (const [size, path] of Object.entries(manifest.action?.default_icon ?? {})) {
  check(path, `action.default_icon.${size}`);
}

for (const [i, cs] of (manifest.content_scripts ?? []).entries()) {
  for (const f of [...(cs.js ?? []), ...(cs.css ?? [])]) check(f, `content_scripts[${i}]`);
}

for (const [i, entry] of (manifest.web_accessible_resources ?? []).entries()) {
  for (const res of entry.resources ?? []) {
    if (res.includes('*')) continue;
    check(res, `web_accessible_resources[${i}]`);
  }
}

for (const [i, rs] of (manifest.declarative_net_request?.rule_resources ?? []).entries()) {
  check(rs.path, `declarative_net_request.rule_resources[${i}]`);
}

/* Chrome rejects an MV3 extension whose manifest_version is not 3, and
   silently tolerates a missing version. Both are worth naming here rather
   than discovering at upload time. */
if (manifest.manifest_version !== 3) {
  failures.push(`manifest_version is ${manifest.manifest_version}, expected 3`);
}
if (!/^\d+(\.\d+){0,3}$/.test(manifest.version ?? '')) {
  failures.push(`version "${manifest.version}" is not a valid Chrome extension version string`);
}

notes.unshift(`checked ${seen.size} referenced path(s) in ${distDir.replace(root + '/', '')}/manifest.json`);
process.exit(report('manifest refs guard', failures, notes));
